test('renderInvoiceText: shows per-line discount for single line with discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert(result.ok);
  const text = renderInvoiceText(result.value);

  // Should show line discount separately (per-line discount)
  assert(text.includes('Discount: -€47.50'));
});

test('renderInvoiceText: shows per-line discount for multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 3, discountPercent: 20 },
    ],
  });

  assert(result.ok);
  const text = renderInvoiceText(result.value);

  // Both line items should have discount lines
  const lines = text.split('\n');
  const discountLines = lines.filter((l) => l.includes('Discount: -'));
  assert(discountLines.length >= 2);
});

test('renderInvoiceText: with bulk discount shows per-line discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 50 }],
  });

  assert(result.ok);
  const text = renderInvoiceText(result.value);

  // 50 x 95 = 4750, bulk discount 2.5% = 118.75
  assert(text.includes('Discount: -€118.75'));
});

test('renderInvoiceText: with voucher shows voucher line before total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    voucher: { amount: 5000 },
  });

  assert(result.ok);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  const voucherIndex = lines.findIndex((l) => l.includes('Voucher:'));
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));

  assert(voucherIndex !== -1, 'Voucher line should be present');
  assert(voucherIndex < totalIndex, 'Voucher should be before total');
  assert(text.includes('Voucher: -€50.00'));
});

