import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, lines: Array<{ qty: number, name: string, unitPrice: number, vatRate: number, discountPercent?: number }>, dueDate?: string, voucher?: { amount: number }, payments?: Array<{ amount: number }> }}
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown customer';

  // Build lines array
  const lines = [];

  // First line: invoice number or DRAFT
  lines.push(invoice.number ?? 'DRAFT');

  // Second line: customer name
  lines.push(customerName);

  // Line items with per-line discounts
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const lineParts = [
      `${line.qty}x ${line.name}`,
      formatEuros(line.unitPrice),
      formatEuros(total),
    ];
    lines.push(lineParts.join(' '));

    // Add per-line discount if it exists
    const discount = lineDiscount(line);
    if (discount > 0) {
      lines.push(`  Discount: -${formatEuros(discount)}`);
    }
  }

  // Calculate totals
  const totals = invoiceTotals(invoice);

  // Show subtotal and discount if any
  if (totals.discount > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }

  // Show VAT if any
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Show voucher if any (just before total)
  if (totals.voucher > 0) {
    lines.push(`Voucher: -${formatEuros(totals.voucher)}`);
  }

  // Total line
  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Due date if invoice has one
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid amount if there are payments
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}

