    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const text = renderInvoiceText(result.value);

  // 5 x 95 = 475, 2.5% discount = 11.88 (rounded)
  // VAT on 463.12 at 21% = 97.26 (rounded)
  // Total: 560.38
