  assert(text.includes('Discount: -€11.88'));
  assert(text.includes('VAT: €97.26'));
  assert(text.includes('Total: €560.38'));
});

test('renderInvoiceText: with tier discount (standard customer)', () => {
  // C-002 is standard tier (0% discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const text = renderInvoiceText(result.value);

  // Standard tier has no discount, so no discount/subtotal lines shown
